// Handles cross-realm cases (e.g., iframes, different JS contexts) where `instanceof` fails.
const isErrorType = (error: unknown, cls: {name: string}): boolean =>
	error instanceof (cls as any) || (error as any)?.name === cls.name;

/**
Type guard to check if an error is a `KyError`.

Note: `SchemaValidationError` is intentionally not considered a Ky error. `KyError` covers failures in Ky's HTTP lifecycle (bad status, timeout, retry), while schema validation errors originate from the user-provided schema, not from Ky itself.

@param error - The error to check
@returns `true` if the error is a Ky error, `false` otherwise

@param error - The error to check
@returns `true` if the error is a Ky error, `false` otherwise

@example
```
import ky, {isKyError} from 'ky';
try {
	const response = await ky.get('/api/data');
} catch (error) {
	if (isKyError(error)) {
		// Handle Ky-specific errors
		console.log('Ky error occurred:', error.message);
	} else {
		// Handle other errors
		console.log('Unknown error:', error);
	}
}
```
*/
export function isKyError(error: unknown): error is KyError {
	return (error as any)?.isKyError === true || isHTTPError(error) || isNetworkError(error) || isTimeoutError(error) || isForceRetryError(error);
}

/**
Type guard to check if an error is an `HTTPError`.

@param error - The error to check
@returns `true` if the error is an `HTTPError`, `false` otherwise

@example
```
import ky, {isHTTPError} from 'ky';
try {
	const response = await ky.get('/api/data');
} catch (error) {
	if (isHTTPError(error)) {
		console.log('HTTP error status:', error.response.status);
	}
}
```
*/
export function isHTTPError<T = unknown>(error: unknown): error is HTTPError<T> {
	return isErrorType(error, HTTPError);
}

/**
Type guard to check if an error is a `NetworkError`.

/**
Type guard to check if an error is a `NetworkError`.

@param error - The error to check
@returns `true` if the error is a `NetworkError`, `false` otherwise

@example
```
import ky, {isNetworkError} from 'ky';
try {
	const response = await ky.get('/api/data');
} catch (error) {
	if (isNetworkError(error)) {
		console.log('Network error:', error.request.url);
	}
}
```
*/
export function isNetworkError(error: unknown): error is NetworkError {
	return isErrorType(error, NetworkError);
}

/**
Type guard to check if an error is a `TimeoutError`.

@param error - The error to check
@returns `true` if the error is a `TimeoutError`, `false` otherwise

@example
```
import ky, {isTimeoutError} from 'ky';
try {
	const response = await ky.get('/api/data', { timeout: 1000 });
} catch (error) {
	if (isTimeoutError(error)) {
		console.log('Request timed out:', error.request.url);
	}
}
```
*/
export function isTimeoutError(error: unknown): error is TimeoutError {
	return isErrorType(error, TimeoutError);
}

/**
Type guard to check if an error is a `ForceRetryError`.

@param error - The error to check
@returns `true` if the error is a `ForceRetryError`, `false` otherwise

/**
Type guard to check if an error is a `ForceRetryError`.

@param error - The error to check
@returns `true` if the error is a `ForceRetryError`, `false` otherwise

@example
```
import ky, {isForceRetryError} from 'ky';

const api = ky.extend({
	hooks: {
		beforeRetry: [
			({error, retryCount}) => {
				if (isForceRetryError(error)) {
					console.log(`Forced retry #${retryCount}: ${error.code}`);
				}
			}
		]
	}
});
```
*/
export function isForceRetryError(error: unknown): error is ForceRetryError {
	return isErrorType(error, ForceRetryError);
}

export type Mutable<T> = {
	-readonly[P in keyof T]: T[P]
};

export type ObjectEntries<T> = T extends ArrayLike<infer U>
	? Array<[string, U]>
	: Array<{[K in keyof T]: [K, T[K]]}[keyof T]>;

import test from 'ava';
import ky from '../source/index.js';
import {createHttpTestServer} from './helpers/create-http-test-server.js';

test('baseUrl option', async t => {
	const server = await createHttpTestServer();
	const serverHost = new URL(server.url).host;
	server.get('/', (_request, response) => {
		response.end('/');
	});
	server.get('/foo', (_request, response) => {
		response.end('/foo');
	});
	server.get('/bar', (_request, response) => {
		response.end('/bar');
	});
	server.get('/foo/bar', (_request, response) => {
		response.end('/foo/bar');
	});
	server.get('/api/v1/users', (_request, response) => {
		response.end('/api/v1/users');
	});

t.is(
		// @ts-expect-error {baseUrl: boolean} isn't officially supported
		await ky(`${server.url}/foo/bar`, {baseUrl: false}).text(),
		'/foo/bar',
	);
	t.is(await ky(`${server.url}/foo/bar`, {baseUrl: '/api'}).text(), '/foo/bar');
	t.is(await ky(`${server.url}/foo/bar`, {baseUrl: ''}).text(), '/foo/bar');
	t.is(await ky(new URL(`${server.url}/foo/bar`), {baseUrl: ''}).text(), '/foo/bar');
	t.is(await ky(new URL(`${server.url}/foo/bar`), {baseUrl: `${server.url}/api/`}).text(), '/foo/bar');
	t.is(await ky(new Request(`${server.url}/foo/bar`), {baseUrl: `${server.url}/api/`}).text(), '/foo/bar');
	t.is(await ky('foo/bar', {baseUrl: server.url}).text(), '/foo/bar');
	t.is(await ky(`//${serverHost}/foo/bar`, {baseUrl: `${server.url}/api/`}).text(), '/foo/bar');
	t.is(await ky('/users', {prefix: 'v1', baseUrl: `${server.url}/api/`}).text(), '/api/v1/users');
	t.is(await ky('foo/bar', {baseUrl: new URL(server.url)}).text(), '/foo/bar');
	t.is(await ky('/bar', {baseUrl: `${server.url}/foo/`}).text(), '/bar');
	t.is(await ky('/bar', {baseUrl: `${server.url}/foo`}).text(), '/bar');
	t.is(await ky('bar', {baseUrl: `${server.url}/foo/`}).text(), '/foo/bar');

t.is(await ky('/bar', {baseUrl: `${server.url}/foo`}).text(), '/bar');
	t.is(await ky('bar', {baseUrl: `${server.url}/foo/`}).text(), '/foo/bar');
	t.is(await ky('bar', {baseUrl: `${server.url}/foo`}).text(), '/bar');
	t.is(await ky('bar', {baseUrl: new URL(`${server.url}/foo`)}).text(), '/bar');
	t.is(await ky('', {baseUrl: server.url}).text(), '/');
	t.is(await ky('', {baseUrl: `${server.url}/`}).text(), '/');
	t.is(await ky('', {baseUrl: new URL(server.url)}).text(), '/');

await server.close();
});

test('baseUrl is exposed on normalized hook options', async t => {
	const server = await createHttpTestServer();
	let receivedBaseUrl: URL | string | undefined;

	server.get('/api/status', (_request, response) => {
		response.end('ok');
	});

	await ky('status', {
		baseUrl: `${server.url}/api/`,
		hooks: {
			beforeRequest: [
				({options}) => {
					receivedBaseUrl = options.baseUrl;
				},
			],
		},
	}).text();

	t.is(receivedBaseUrl, `${server.url}/api/`);

	await server.close();
});

import test from 'ava';
import {getBodySize} from '../source/utils/body.js';

test('returns 0 for undefined', t => {
	t.is(getBodySize(undefined), 0);
});

test('returns 0 for null', t => {
	t.is(getBodySize(null), 0);
});

test('returns correct size for ASCII string', t => {
	t.is(getBodySize('hello'), 5);
});

test('returns correct size for multi-byte string', t => {
	// Emoji is 4 bytes in UTF-8
	t.is(getBodySize('😀'), 4);
	t.is(getBodySize('hello 😀 world'), 16);
});

test('returns correct size for empty string', t => {
	t.is(getBodySize(''), 0);
});

test('returns correct size for ArrayBuffer', t => {
	const buffer = new ArrayBuffer(16);
	t.is(getBodySize(buffer), 16);
});

test('returns correct size for Uint8Array', t => {
	const array = new Uint8Array([1, 2, 3, 4, 5]);
	t.is(getBodySize(array), 5);
});

test('returns correct size for Uint16Array', t => {
	const array = new Uint16Array([1, 2, 3]);
	t.is(getBodySize(array), 6); // 3 elements × 2 bytes
});

test('returns correct size for Float64Array', t => {
	const array = new Float64Array([1, 2]);
	t.is(getBodySize(array), 16); // 2 elements × 8 bytes
});

test('returns correct size for Float64Array', t => {
	const array = new Float64Array([1, 2]);
	t.is(getBodySize(array), 16); // 2 elements × 8 bytes
});

test('returns correct size for DataView', t => {
	const buffer = new ArrayBuffer(10);
	const view = new DataView(buffer);
	t.is(getBodySize(view), 10);
});

test('returns correct size for TypedArray subarray', t => {
	const full = new Uint8Array([1, 2, 3, 4, 5]);
	const sub = full.subarray(1, 3);
	// Should return the view's byteLength (2), not the underlying buffer's (5)
	t.is(getBodySize(sub), 2);
});

test('returns 0 for zero-length ArrayBuffer', t => {
	t.is(getBodySize(new ArrayBuffer(0)), 0);
});

test('returns correct size for Blob', t => {
	const blob = new Blob(['hello world']);
	t.is(getBodySize(blob), 11);
});

test('returns correct size for Blob with multi-byte content', t => {
	const blob = new Blob(['😀']);
	t.is(getBodySize(blob), 4);
});

test('returns correct size for File', t => {
	const file = new File(['hello world'], 'test.txt', {type: 'text/plain'});
	t.is(getBodySize(file), 11);
});

test('returns correct size for File', t => {
	const file = new File(['hello world'], 'test.txt', {type: 'text/plain'});
	t.is(getBodySize(file), 11);
});

test('returns correct size for URLSearchParams', t => {
	const parameters = new URLSearchParams({foo: 'bar', baz: 'qux'});
	t.is(getBodySize(parameters), 15); // 'foo=bar&baz=qux'
});

test('returns correct size for empty URLSearchParams', t => {
	const parameters = new URLSearchParams();
	t.is(getBodySize(parameters), 0);
});

test('returns 0 for ReadableStream', t => {
	const stream = new ReadableStream();
	t.is(getBodySize(stream), 0);
});

test('returns 0 for empty FormData', t => {
	const formData = new FormData();
	t.is(getBodySize(formData), 0);
});

test('FormData returns a positive size', t => {
	const formData = new FormData();
	formData.append('key', 'value');
	const size = getBodySize(formData);
	t.true(size > 0, `Expected positive size, got ${size}`);
});

test('FormData size increases with more fields', t => {
	const formData1 = new FormData();
	formData1.append('a', '1');
	const size1 = getBodySize(formData1);

test('FormData size increases with more fields', t => {
	const formData1 = new FormData();
	formData1.append('a', '1');
	const size1 = getBodySize(formData1);

	const formData2 = new FormData();
	formData2.append('a', '1');
	formData2.append('b', '2');
	const size2 = getBodySize(formData2);

	t.true(size2 > size1, `Two fields (${size2}) should be larger than one field (${size1})`);
});

test('FormData with Blob value accounts for blob size', t => {
	const formData = new FormData();
	formData.append('file', new Blob(['hello world']));

	const size = getBodySize(formData);
	// Size should be at least the blob content size (11 bytes)
	t.true(size >= 11, `Expected size >= 11, got ${size}`);
});

import test, {type ExecutionContext} from 'ava';
import busboy from 'busboy';
import express from 'express';
import {
	chromium,
	firefox,
	webkit,
	type Page,
} from 'playwright';
import type ky from '../source/index.js';
import type {Progress} from '../source/index.js';
import {createHttpTestServer, type ExtendedHttpTestServer, type HttpServerOptions} from './helpers/create-http-test-server.js';
import {parseRawBody} from './helpers/parse-body.js';
import {browserTest, defaultBrowsersTest} from './helpers/with-page.js';

declare global {
	// eslint-disable-next-line @typescript-eslint/consistent-type-definitions
	interface Window {
		ky: typeof ky;
	}
}

const DIST_DIR = new URL('../distribution', import.meta.url).toString();
const createEsmTestServer = async (options?: HttpServerOptions) => {
	const server = await createHttpTestServer(options);
	server.use('/distribution', express.static(DIST_DIR.replace(/^file:\/\//, '')));
	server.use((_, response, next) => {
		response.set('Connection', 'close');
		next();
	});
	return server;
};

const KY_SCRIPT = {
	type: 'module',
	content: `
		import ky from '/distribution/index.js';
		globalThis.ky = ky;
	`,
};
const addKyScriptToPage = async (page: Page) => {
	await page.addScriptTag(KY_SCRIPT);
	await page.waitForFunction(() => typeof globalThis.ky === 'function');
};

let server: ExtendedHttpTestServer;
test.beforeEach(async () => {
	server = await createEsmTestServer();
});

test.afterEach(async () => {
	await server.close();
});

defaultBrowsersTest('baseUrl option', async (t: ExecutionContext, page: Page) => {
	server.get('/', (_request, response) => {
		response.end('zebra');
	});

	server.get('/unicorn', (_request, response) => {
		response.end('charlie');
	});

	server.get('/api/unicorn', (_request, response) => {
		response.end('rainbow');
	});

	await page.goto(server.url);
	await addKyScriptToPage(page);

server.get('/api/unicorn', (_request, response) => {
		response.end('rainbow');
	});

	await page.goto(server.url);
	await addKyScriptToPage(page);

	const results = await page.evaluate(async (url: string) => Promise.all([
		globalThis.ky(`${url}/api/unicorn`).text(),
		// @ts-expect-error unsupported {baseUrl: null} type
		globalThis.ky(`${url}/api/unicorn`, {baseUrl: null}).text(),
		globalThis.ky('api/unicorn', {baseUrl: url}).text(),
		globalThis.ky('unicorn', {baseUrl: `${url}/api`}).text(),
		globalThis.ky('/unicorn', {baseUrl: `${url}/api`}).text(),
		globalThis.ky('unicorn', {baseUrl: `${url}/api/`}).text(),
		globalThis.ky('/unicorn', {baseUrl: `${url}/api/`}).text(),
	]), server.url);

	t.deepEqual(results, ['rainbow', 'rainbow', 'rainbow', 'charlie', 'charlie', 'rainbow', 'charlie']);
});

